require'json';require'fileutils';root=File.expand_path('..',__dir__);source=JSON.parse(File.read(File.join(root,'protocol/aoo-protocol-v2.json')));ts=File.read(File.expand_path('../Client/assets/Common/Code/Runtime/network/GeneratedProtocolIds.ts',root));types=source.fetch('messages').flat_map{|m|%w[request response].flat_map{|side|m.fetch(side).fetch('properties').values}}.uniq.sort;checks={all_machine_types_documented:types.all?{|type|File.read(File.join(root,'protocol/TYPE_MAPPING.md')).include?("| #{type}")},typescript_scalar_mapping:%w[string number boolean Readonly].all?{|token|ts.include?(token)},required_optional_mapping:ts.match?(/\?\:|\?\:/),id_string_rule:File.read(File.join(root,'protocol/TYPE_MAPPING.md')).include?('业务 ID'),bytes_enum_map_optional_policy:%w[bytes enum optional map].all?{|word|File.read(File.join(root,'protocol/TYPE_MAPPING.md')).include?(word)}};checks[:passed]=checks.values.all?;out=File.join(root,'docs/generated/proto08-type-mapping.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(checks.merge(machineTypes:types))+"\n");abort('PROTO08 type mapping audit failed')unless checks[:passed]
